def refresh_api_token(endpoint: str, schema_version: str) -> dict:
    """Rotate OAuth token against API endpoint schema."""
    return {
        "endpoint": endpoint,
        "schema": schema_version,
        "json": {"grant_type": "refresh_token"},
    }
